"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0878-01-01:0":{"b": ["Edington (Ethandun) döyüşü və Wedmore sülhü: Alfred danimarkalıları (Guthrum) məğlub edir", "bb82711f"], "d": ["878-in yanvarında danimarkalıların Chippenhama qəfil basqınından sonra Alfred az adamla gizləndi; ordular Wiltshiredəki Edingtonda qarşılaşdı. Wedmore sülhündən (878) sonra danimarkalılar Wessexdən çəkildi, London daxil şimal-şərq yarısı danimarkalılarda qaldı, lakin 'gelgit dönmüşdü'.", "4f02f617"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0878-05-21:0":{"b": ["Ərəblər Sirakuzanı aldı", "0ad38c19"], "d": ["Əğləbilər uzun mühasirədən sonra Siciliyanın başlıca Bizans mərkəzi Sirakuzanı 21 may 878-də ələ keçirdi; ada Bizansın əlindən faktiki çıxmağa başladı.", "3c2d97da"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0886-01-01:0":{"b": ["Alfred Londonu danimarkalılardan alır; Alfred-Guthrum sülhü sərhədləri Alfred xeyrinə dəyişir", "32d8daf9"], "d": ["Alfred, üsyançı danimarkalılara qarşı gördüyü tədbirlərin sonunda Londonu 885 və ya 886-da ələ keçirdi; Alfred ilə Guthrum arasında Wedmore sərhədlərini Alfred xeyrinə dəyişən sülh bağlandı.", "01209a4c"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0893-01-01:0":{"b": ["III Alfonso dövründə Zamora məskunlaşdırıldı.", "78edf65c"], "d": ["III Alfonso dövründə Zamora məskunlaşdırıldı.", "78edf65c"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0893-03-23:0":{"b": ["Samani əmiri İsmayıl ibn Əhməd Talası (Taraz) ələ keçirdi; Samanilər şərqdə ən geniş sərhədlərinə çatdı", "a25f7598"], "d": ["İsmayıl ibn Əhməd qeyri-müsəlman türklərin basqınlarına qarşı Mavərənnəhri qorumaq üçün Taraza (Talas) qədər uzanan yürüş təşkil edib şəhəri ələ keçirdi; buradakı türk əmir və dehqanlarının çoxu müsəlman oldu, Şərqi Qaraxanlı mərkəzi Talası itirən Oğulçaq paytaxtı Kaşqara köçürdü.", "8bf208a3"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0902-08-01:0":{"b": ["Taormina süquta uğradı: Bizansın Siciliyadakı son qalası itirildi", "525abc8c"], "d": ["Taorminanın ərəblər tərəfindən ələ keçirilməsi ilə Bizansın Siciliya adasındakı hakimiyyəti sona çatdı; yalnız Cənubi İtaliyadakı torpaqlar qaldı.", "9e2eb491"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0903-01-01:0":{"b": ["Qərmətilər Həma, Hims, Məərrətən-Nöman və Baalbəkki ələ keçirdi; göndərilən Tolunilər birlikləri məğlub oldu (290/903).", "291ecf32"], "d": ["Qərmətilər Həma, Hims, Məərrətən-Nöman və Baalbəkki ələ keçirdi; göndərilən Tolunilər birlikləri məğlub oldu (290/903).", "291ecf32"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0911-01-01:0":{"b": ["Kan-chou Uyğur ordusu Tun-huangı ələ keçirdi", "36ec7038"], "d": ["905-də Çinli komandanın qurduğu muxtar krallığın mərkəzi Tun-huang 911-də Tegin komandanlığı altındakı Uyğur ordusu tərəfindən alındı; qələbə Kan-chou Uyğurlarının çinlilər yanında nüfuzunu artırdı.", "3bffe840"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0914-01-01:0":{"b": ["Simeon Adrianopolu aldı", "fe0efa60"], "d": ["Bulqar çarı Simeon 914-də Hadrianopolisi (Adrianopol) ələ keçirdi; şəhər Bizans və Bulqar müharibələrinin uzun müddət səhnəsi oldu.", "0d8b77bc"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0923-11-19:0":{"b": ["Li Cunxu Kaifenqə daxil oldu: Sonrakı Liang yıxıldı", "aebaab18"], "d": ["Zhongduda Liang ordusunu darmadağın edən Li Cunxunun öncülü Li Siyuan gün doğarkən Kaifengin Fengqiu darvazasına dayandı; Liangın Kaifeng valisi Wang Zan şəhəri təslim etdi, Li Cunxu Daliang darvazasından şəhərə daxil oldu.", "4ee60f2e"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0934-01-01:0":{"b": ["Bizans Malatyanı aldı", "fd0898d0"], "d": ["Şərq domestikosu Ioannes Kourkouasın komandanlığı altındakı Bizans ordusu Fıratadək irəlilədi və 934-də Malatyanı ələ keçirdi; 943-də Meyyafarikin, Amid, Dara və Nusaybin də alındı.", "46c833cc"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0943-01-01:0":{"b": ["Mərzübən Azərbaycan, Arran və İrminiyənin nəzarətini ələ alır (330-331 / 942-943).", "fc600309"], "d": ["Mərzübən Azərbaycan, Arran və İrminiyənin nəzarətini ələ alır (330-331 / 942-943).", "fc600309"]},
